param (
    [Parameter(Mandatory=$true)]
    [string]$RepoName
)

# Include php.ini with extension settings, generated by build-project
$sep = [IO.Path]::PathSeparator
$env:PHP_INI_SCAN_DIR = "$sep$PWD/$RepoName"

# Without the TAC data file that php.ini names, PHP starts with the extension
# and no engine. The WithoutTacFile suite then runs the tests that use the
# Lite data file or none, which include every test of the examples with no
# settings. The options are those common-ci's php/run-unit-tests.ps1 gives.
if (!(Test-Path assets/TAC-HashV41.hash)) {
    Write-Output "::warning file=$($MyInvocation.ScriptName),line=$($MyInvocation.ScriptLineNumber),title=No On-Premise Data File::On-Premise Data File wasn't found, so only the unit tests that need no TAC data file will run."
    $options = @('--fail-on-warning')
    & {
        $PSNativeCommandUseErrorActionPreference = $false
        phpunit --atleast-version=10 | Out-Null
    }
    if ($LASTEXITCODE -eq 0) {
        $options += '--display-warnings'
    }
    Push-Location $RepoName
    try {
        phpunit $options --testsuite WithoutTacFile --log-junit test-results/unit/$RepoName/tests.xml
    } finally {
        Pop-Location
    }
    exit $LASTEXITCODE
}

./php/run-unit-tests.ps1 -RepoName $RepoName

# Run configuration tests. The concurrency test exercises the engine under the
# PHP built-in server. It previously failed on macOS (see issue #38) and so was
# limited to Linux, but the underlying problem is now fixed by always using the
# in-memory MaxPerformance profile, so it runs on every platform.
& $RepoName/configuration-tests/testConcurrencySetting.ps1 -BaseIniFilePath $PWD/$RepoName/php.ini || $(throw "concurrency configuration tests failed")

# Demonstrate why a non in-memory profile is rejected: a streaming profile fails
# across a fork (as used by process managers) while the in-memory profile is
# safe.
& $RepoName/configuration-tests/testForkSafety.ps1 -RepoName $RepoName || $(throw "fork-safety test failed")

exit $LASTEXITCODE
